// login.js
import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";

function Login() {
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [error, setError] = useState("");
    const navigate = useNavigate();

    const handleLogin = async (e) => {
        e.preventDefault();
        setError("");

        try {
            const apiURL = `https://novaoffice.novasoftwares.com/service.aspx?ApiVer=1&Devid=online&AppId=NV01&Lat=0&Lng=0&Control=auth&data=${encodeURIComponent(
                JSON.stringify({ userid: email, password })
            )}`;

            const response = await fetch(apiURL);
            const data = await response.json();

            if (data && data.Response && data.Response.Status === "1") {
                // Pass data to dashboard using navigation state
                navigate("/dashboard", { state: { data } });
            } else {
                setError("Invalid credentials. Try again.");
            }
        } catch (err) {
            setError("Something went wrong. Please try again.");
            console.error(err);
        }
    };

    return (
        <div className="container">
            <h1>Login</h1>
            <form onSubmit={handleLogin}>
                <div className="field">
                    <label>Email (UserID)</label>
                    <input
                        type="text"
                        name="email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        placeholder="User ID"
                    />
                </div>
                <div className="field">
                    <label>Password</label>
                    <input
                        type="password"
                        name="password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        placeholder="Password"
                    />
                </div>
                <button className="fluid ui button blue" type="submit">
                    Login
                </button>
                {error && <p style={{ color: "red" }}>{error}</p>}
            </form>
            <div className="text">
                Don't have an account? <Link to="/signup">Sign up</Link>
            </div>
        </div>
    );
}

export default Login;
